<script lang="ts" setup>
import type { ConditionLogic, RuleCondition, RuleDraft, RuleTransition, RuleType } from '../types';
import { computed, reactive, watch } from 'vue';
const props = defineProps<{ open: boolean }>();
const emit = defineEmits<{ 'update:open': [value: boolean]; save: [draft: RuleDraft] }>();
const fields = ['节律', 'CPR 轮次', '是否 ROSC', '有效除颤完成', '安全清场', 'ETCO₂', '按压中断时长', '除颤次数', '导师暂停', '设备状态'];
const operators = ['等于', '不等于', '大于', '小于', '小于等于', '已完成', '未完成'];
const blankCondition = (): RuleCondition => ({ id: `condition-${Date.now()}-${Math.random()}`, field: '节律', operator: '等于', value: 'VF/pVT' });
const form = reactive<{ name: string; type: RuleType; conditionLogic: ConditionLogic; conditions: RuleCondition[]; deadlineSeconds: number; effectsText: string; scoreChange: number; transition: RuleTransition; oncePerCycle: boolean }>({ name: '', type: 'main', conditionLogic: 'all', conditions: [blankCondition()], deadlineSeconds: 120, effectsText: '记录事件', scoreChange: 0, transition: 'stayCurrentStage', oncePerCycle: true });
const readableRule = computed(() => `${form.conditions.map((item) => `${item.field}${item.operator}${item.value}`).join(form.conditionLogic === 'all' ? ' 且 ' : ' 或 ')}；${form.deadlineSeconds} 秒内触发；${form.effectsText}`);
function close() { emit('update:open', false); }
function addCondition() { form.conditions.push(blankCondition()); }
function removeCondition(index: number) { if (form.conditions.length > 1) form.conditions.splice(index, 1); }
function submit() { if (!form.name.trim()) return; emit('save', { name: form.name.trim(), type: form.type, conditionLogic: form.conditionLogic, conditions: form.conditions.map((item) => ({ ...item })), deadlineSeconds: form.deadlineSeconds, effects: form.effectsText.split(/[、,，]/).map((item) => item.trim()).filter(Boolean), scoreChange: form.scoreChange, transition: form.transition, oncePerCycle: form.oncePerCycle }); }
watch(() => props.open, (isOpen) => { if (isOpen) { form.name = ''; form.type = 'main'; form.conditionLogic = 'all'; form.conditions = [blankCondition()]; form.deadlineSeconds = 120; form.effectsText = '记录事件'; form.scoreChange = 0; form.transition = 'stayCurrentStage'; form.oncePerCycle = true; } });
</script>
<template>
  <Teleport to="body"><div v-if="props.open" class="backdrop" @click.self="close"><section class="panel"><header class="flex items-start justify-between gap-4 border-b border-border pb-4"><div><h2 class="text-lg font-semibold">添加可执行规则</h2><p class="mt-1 text-sm text-muted-foreground">设置条件、时限、临床后果、评分与确定性路径去向。</p></div><button @click="close">✕</button></header><div class="mt-5 grid gap-4 md:grid-cols-2"><label class="field">规则名称<input v-model="form.name" placeholder="例如：VF/pVT 除颤延误" /></label><label class="field">规则类型<select v-model="form.type"><option value="main">主路径</option><option value="delay">延误分支</option><option value="safety">严重安全事件</option></select></label></div><section class="mt-5 rounded-lg border border-border p-4"><div class="flex flex-wrap items-center justify-between gap-3"><h3 class="font-semibold">判定条件</h3><select v-model="form.conditionLogic" class="input w-auto"><option value="all">全部满足（AND）</option><option value="any">任一满足（OR）</option></select></div><div class="mt-3 space-y-2"><div v-for="(condition, index) in form.conditions" :key="condition.id" class="grid gap-2 sm:grid-cols-[1fr_1fr_1fr_auto]"><select v-model="condition.field" class="input"><option v-for="field in fields" :key="field">{{ field }}</option></select><select v-model="condition.operator" class="input"><option v-for="operator in operators" :key="operator">{{ operator }}</option></select><input v-model="condition.value" class="input" /><button class="rounded-md px-2 text-sm text-red-600 disabled:opacity-40" :disabled="form.conditions.length === 1" @click="removeCondition(index)">删除</button></div></div><button class="btn-secondary mt-3" @click="addCondition">＋ 添加条件</button></section><div class="mt-5 grid gap-4 md:grid-cols-3"><label class="field">判定时限（秒）<input v-model.number="form.deadlineSeconds" type="number" min="0" /></label><label class="field">评分变化<input v-model.number="form.scoreChange" type="number" /></label><label class="field">路径去向<select v-model="form.transition"><option value="stayCurrentStage">留在当前阶段</option><option value="nextStage">进入下一阶段</option><option value="nextCycle">下一 CPR 周期</option><option value="instructorIntervention">导师介入</option><option value="debriefExit">复盘出口</option></select></label></div><label class="field mt-4">临床后果（以逗号分隔）<input v-model="form.effectsText" /></label><label class="mt-4 flex items-center gap-2 text-sm"><input v-model="form.oncePerCycle" type="checkbox" />单轮最多触发一次，避免重复执行或扣分</label><div class="mt-5 rounded-lg bg-muted p-3 text-sm"><b>规则预览：</b>{{ readableRule }}</div><footer class="mt-6 flex justify-end gap-2"><button class="btn-secondary" @click="close">取消</button><button class="btn-primary" :disabled="!form.name.trim()" @click="submit">保存规则</button></footer></section></div></Teleport>
</template>
<style scoped>.backdrop { @apply fixed inset-0 z-50 flex items-center justify-center overflow-y-auto bg-slate-950/50 p-4; }.panel { @apply my-auto w-full max-w-4xl rounded-xl bg-card p-5 shadow-xl; }.field { @apply grid gap-1.5 text-sm font-medium; }.field input,.field select,.input { @apply rounded-md border border-border bg-background px-3 py-2 text-sm font-normal outline-none focus:border-primary; }.btn-primary { @apply rounded-md bg-primary px-3 py-2 text-sm font-medium text-primary-foreground disabled:opacity-50; }.btn-secondary { @apply rounded-md border border-border px-3 py-2 text-sm hover:bg-muted; }</style>
